do $$ begin if exists ( select 1 from information_schema.columns where table_schema = 'public' and table_name = 'fx_rates' and column_name = 'rate_to_gbp' ) then alter table public.fx_rates rename column rate_to_gbp to rate_to_base; alter table public.fx_rates rename column previous_rate_to_gbp to previous_rate_to_base; end if; end; $$;
alter table public.fx_rates add column if not exists base_currency char(3) not null default 'USD';
comment on column public.fx_rates.rate_to_base is 'One unit of `currency` in `base_currency`. GBP 1.00 -> 1.34 USD means rate_to_base = 1.34.';
do $$ begin if exists ( select 1 from information_schema.columns where table_schema = 'public' and table_name = 'price_calculations' and column_name = 'cost_gbp_minor' ) then alter table public.price_calculations rename column cost_gbp_minor to cost_base_minor; end if; end; $$;
comment on column public.price_calculations.cost_base_minor is 'The publisher price converted into our currency, before fees and VAT.';
do $$ declare rate constant numeric := 1.34; on_gbp boolean; begin select currency = 'GBP' into on_gbp from public.settings limit 1; if not coalesce(on_gbp, false) then raise notice 'Already off GBP - prices and bands left exactly as they are.'; return; end if; -- Every stored rate was against pounds and is now meaningless. Cleared -- rather than converted: a wrong rate priced confidently is worse than no -- rate, and pricing already refuses to guess when one is missing. Press -- Refresh rates on the pricing screen after running this. delete from public.fx_rates; insert into public.fx_rates (currency, rate_to_base, base_currency, source) values ('USD', 1, 'USD', 'fixed') on conflict (currency) do nothing; -- The same margins, restated. Converted rather than reinvented so nothing -- about what we earn changes on the day of the switch. They are rows and -- can be edited on the pricing screen afterwards. update public.pricing_rules set min_margin_minor = round(min_margin_minor * rate), -- PayPal's fixed fee is charged in the currency of the payment, so -- 30p becomes 30 cents rather than 40. paypal_fee_fixed_minor = 30, bank_fee_fixed_minor = round(bank_fee_fixed_minor * rate) where id = 1; update public.pricing_bands set min_cost_minor = round(min_cost_minor * rate), flat_minor = case when flat_minor is null then null else round(flat_minor * rate) end; -- A tier boundary of "about a thousand" stays about a thousand. update public.pricing_rounding set min_minor = round(min_minor * rate); -- Converted before anything is recalculated, so there is no window in which -- a listing that sold for 145 pounds is offered for 145 dollars. A -- recalculation afterwards re-derives the engine-set ones from cost; the -- hand-set ones keep these numbers, which is why they must be converted -- rather than left for the engine. update public.services set price_minor = round(price_minor * rate), agency_price_minor = case when agency_price_minor is null then null else round(agency_price_minor * rate) end; update public.website_niche_prices set price_minor = round(price_minor * rate), agency_price_minor = case when agency_price_minor is null then null else round(agency_price_minor * rate) end; -- Every row was worked out in pounds. It is a cache of a calculation, so it -- is emptied rather than converted and fills again on the next run. delete from public.price_calculations; -- Last, because it is the flag this whole block is guarded on. update public.settings set currency = 'USD'; raise notice 'Converted to USD at %. Refresh the rates, then recalculate.', rate; end; $$;
